<script>
export default {
  name: 'SvgMainLoaderSecondStage',
  mounted() {
    const svg = this.$refs.svg;
    const path = svg.querySelector('path#done');
    var pfx = ['webkit', 'moz', 'MS', 'o', ''];
    const PrefixedEvent = (element, type, callback) => {
      for (var p = 0; p < pfx.length; p++) {
        if (!pfx[p]) type = type.toLowerCase();
        element.addEventListener(pfx[p] + type, callback, false);
      }
    };
    PrefixedEvent(path, 'AnimationStart', (e) => {
      this.onBegin(e);
    });
    PrefixedEvent(path, 'AnimationIteration', (e) => {
      this.onRepeat(e);
    });
    PrefixedEvent(path, 'AnimationEnd', (e) => {
      this.onEnd(e);
    });
  },
  methods: {
    onBegin(e) {
      // console.log('BEGIN animation')
      this.$emit('begin', e);
    },
    onEnd(e) {
      this.$emit('end', e);
    },
    onRepeat(e) {
      this.$emit('repeat', e);
    },
  },
};
